on conflict (id) do update set
  name = excluded.name, pack = excluded.pack, rarity = excluded.rarity,
  element = excluded.element, front_image = excluded.front_image,
  power = excluded.power, speed = excluded.speed,
  intelligence = excluded.intelligence, defence = excluded.defence,
  luck = excluded.luck, ability_name = excluded.ability_name,
  ability_description = excluded.ability_description,
  ability_boosts = excluded.ability_boosts, active = true;
